(function()
    local JSON = (function()
        -- A small, correct, dependency-free JSON parser/encoder (pure Luau).
-- No reliance on HttpService, so it behaves identically everywhere.

local JSON = {}

-- ---------------- encode ----------------

local ESCAPES = {
	['"'] = '\\"',
	['\\'] = '\\\\',
	['\b'] = '\\b',
	['\f'] = '\\f',
	['\n'] = '\\n',
	['\r'] = '\\r',
	['\t'] = '\\t',
}

local function encode_string(s)
	local out = string.gsub(s, '[%z\1-\31\\"]', function(c)
		local e = ESCAPES[c]
		if e then
			return e
		end
		return string.format('\\u%04x', string.byte(c))
	end)
	return '"' .. out .. '"'
end

function JSON.encode(val, stack)
	local t = typeof and typeof(val) or type(val)
	if t == "string" then
		return encode_string(val)
	elseif t == "number" then
		return tostring(val)
	elseif t == "boolean" then
		return val and "true" or "false"
	elseif t == "nil" then
		return "null"
	elseif t == "table" then
		stack = stack or {}
		if stack[val] then
			error("Cannot encode recursive tables")
		end
		stack[val] = true

		local n = #val
		local isArray = true
		for k in pairs(val) do
			if type(k) ~= "number" or k < 1 or k > n or k % 1 ~= 0 then
				isArray = false
				break
			end
		end

		local parts = {}
		if isArray then
			for i = 1, n do
				parts[i] = JSON.encode(val[i], stack)
			end
			stack[val] = nil
			return "[" .. table.concat(parts, ",") .. "]"
		end

		local i = 0
		for k, v in pairs(val) do
			i = i + 1
			parts[i] = encode_string(tostring(k)) .. ":" .. JSON.encode(v, stack)
		end
		stack[val] = nil
		return "{" .. table.concat(parts, ",") .. "}"
	end
	error("Cannot encode type: " .. t)
end

-- ---------------- decode ----------------

local function decode(str)
	local pos = 1
	local len = #str

	-- Safety bounds for malformed/hostile payloads: a generous input-size ceiling
	-- and a recursion-depth cap, so deeply nested JSON degrades to a clean error
	-- instead of a native stack overflow. Real VM payloads nest only a handful of
	-- levels and are far below the size limit, so neither trips legitimate builds.
	local MAX_INPUT = 64 * 1024 * 1024 -- 64 MB
	local MAX_DEPTH = 256
	local depth = 0
	if len > MAX_INPUT then
		error("JSON input too large", 0)
	end

	local parseValue -- forward declaration

	local function err(msg)
		error(string.format("JSON parse error at %d: %s", pos, msg), 0)
	end

	local function skipWhitespace()
		while pos <= len do
			local c = string.byte(str, pos)
			-- space, tab, newline, carriage return
			if c == 32 or c == 9 or c == 10 or c == 13 then
				pos = pos + 1
			else
				break
			end
		end
	end

	local function parseString()
		pos = pos + 1 -- skip opening quote
		local chunks = {}
		while pos <= len do
			local c = string.byte(str, pos)
			if c == 34 then -- closing quote
				pos = pos + 1
				return table.concat(chunks)
			elseif c == 92 then -- backslash
				local e = string.byte(str, pos + 1)
				if e == 110 then
					chunks[#chunks + 1] = "\n"
				elseif e == 116 then
					chunks[#chunks + 1] = "\t"
				elseif e == 114 then
					chunks[#chunks + 1] = "\r"
				elseif e == 98 then
					chunks[#chunks + 1] = "\b"
				elseif e == 102 then
					chunks[#chunks + 1] = "\f"
				elseif e == 47 then
					chunks[#chunks + 1] = "/"
				elseif e == 92 then
					chunks[#chunks + 1] = "\\"
				elseif e == 34 then
					chunks[#chunks + 1] = '"'
				elseif e == 117 then -- \uXXXX
					local hex = string.sub(str, pos + 2, pos + 5)
					local code = tonumber(hex, 16)
					pos = pos + 4
					if not code then
						err("invalid unicode escape")
					end
					-- Encode the code point as UTF-8.
					if code < 0x80 then
						chunks[#chunks + 1] = string.char(code)
					elseif code < 0x800 then
						chunks[#chunks + 1] = string.char(
							0xC0 + math.floor(code / 0x40),
							0x80 + (code % 0x40)
						)
					else
						chunks[#chunks + 1] = string.char(
							0xE0 + math.floor(code / 0x1000),
							0x80 + (math.floor(code / 0x40) % 0x40),
							0x80 + (code % 0x40)
						)
					end
				else
					err("invalid escape sequence")
				end
				pos = pos + 2
			else
				chunks[#chunks + 1] = string.char(c)
				pos = pos + 1
			end
		end
		err("unterminated string")
	end

	local function parseNumber()
		local startPos = pos
		while pos <= len do
			local c = string.byte(str, pos)
			-- digits, +, -, ., e, E
			if (c >= 48 and c <= 57) or c == 43 or c == 45 or c == 46 or c == 101 or c == 69 then
				pos = pos + 1
			else
				break
			end
		end
		local numStr = string.sub(str, startPos, pos - 1)
		local num = tonumber(numStr)
		if not num then
			err("invalid number '" .. numStr .. "'")
		end
		return num
	end

	local function parseArray()
		pos = pos + 1 -- skip [
		local arr = {}
		local n = 0
		skipWhitespace()
		if string.byte(str, pos) == 93 then -- ]
			pos = pos + 1
			return arr
		end
		while true do
			skipWhitespace()
			n = n + 1
			arr[n] = parseValue()
			skipWhitespace()
			local c = string.byte(str, pos)
			if c == 44 then -- ,
				pos = pos + 1
			elseif c == 93 then -- ]
				pos = pos + 1
				return arr
			else
				err("expected ',' or ']' in array")
			end
		end
	end

	local function parseObject()
		pos = pos + 1 -- skip {
		local obj = {}
		skipWhitespace()
		if string.byte(str, pos) == 125 then -- }
			pos = pos + 1
			return obj
		end
		while true do
			skipWhitespace()
			if string.byte(str, pos) ~= 34 then
				err("expected string key in object")
			end
			local key = parseString()
			skipWhitespace()
			if string.byte(str, pos) ~= 58 then -- :
				err("expected ':' after key")
			end
			pos = pos + 1
			skipWhitespace()
			obj[key] = parseValue()
			skipWhitespace()
			local c = string.byte(str, pos)
			if c == 44 then -- ,
				pos = pos + 1
			elseif c == 125 then -- }
				pos = pos + 1
				return obj
			else
				err("expected ',' or '}' in object")
			end
		end
	end

	parseValue = function()
		skipWhitespace()
		local c = string.byte(str, pos)
		if c == nil then
			err("unexpected end of input")
		end
		if c == 123 then -- {
			depth = depth + 1
			if depth > MAX_DEPTH then
				err("maximum nesting depth exceeded")
			end
			local v = parseObject()
			depth = depth - 1
			return v
		elseif c == 91 then -- [
			depth = depth + 1
			if depth > MAX_DEPTH then
				err("maximum nesting depth exceeded")
			end
			local v = parseArray()
			depth = depth - 1
			return v
		elseif c == 34 then -- "
			return parseString()
		elseif c == 116 then -- t(rue)
			if string.sub(str, pos, pos + 3) == "true" then
				pos = pos + 4
				return true
			end
			err("invalid literal")
		elseif c == 102 then -- f(alse)
			if string.sub(str, pos, pos + 4) == "false" then
				pos = pos + 5
				return false
			end
			err("invalid literal")
		elseif c == 110 then -- n(ull)
			if string.sub(str, pos, pos + 3) == "null" then
				pos = pos + 4
				return nil
			end
			err("invalid literal")
		else
			return parseNumber()
		end
	end

	local value = parseValue()
	skipWhitespace()
	return value
end

-- Returns (value) on success or (nil, errorMessage) on failure.
function JSON.decode(json_str)
	if typeof and typeof(json_str) ~= "string" then
		return nil, "JSON.decode expects a string"
	end
	local ok, result = pcall(decode, json_str)
	if ok then
		return result
	end
	return nil, tostring(result)
end

return JSON

    end)()

